131				content: "\2197" / "";
132				display: inline-block;
133				margin-inline-start: 0.2em;
134				font-size: 0.8em;
135				text-decoration: none;
136			}
137			button,
138			.button {
139				display: inline-block;
140				text-decoration: none;
141				padding: 0.75rem 1.5rem;
142				font-size: 1rem;
143				font-weight: 500;
144				font-family: inherit;
145				color: var(--background);
