161			}
162			ul, ol {
163				margin: 1rem 0;
164				padding-left: 2rem;
165			}
166			li {
167				margin: 0.5rem 0;
168			}
169			:focus-visible {
170				outline: 2px solid var(--accent);
171				outline-offset: 2px;
172			}
173			a:not(.button):focus-visible {
174				border-radius: 2px;
175			}
